import{_ as p,a0 as r,w as a,s,ao as u,I as l,x as n,a1 as i,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"在 Linux 上管理加密密鑰的最佳體驗 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上管理加密密鑰的最佳體驗 | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上管理加密密鑰的最佳體驗 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上管理加密密鑰的最佳體驗 | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160218 How to Best Manage Encryption Keys on Linux","title":"在 Linux 上管理加密密鑰的最佳體驗","tag":"201607","desc":""},"relativePath":"201607/20160218 How to Best Manage Encryption Keys on Linux.md","filePath":"[post].md"}'),d={name:"201607/20160218 How to Best Manage Encryption Keys on Linux.md"};function m(g,t,x,f,S,w){const e=r("Link");return a(),s("div",null,[t[22]||(t[22]=u(`<h1 id="在-linux-上管理加密密鑰的最佳體驗" tabindex="-1">在 Linux 上管理加密密鑰的最佳體驗 <a class="header-anchor" href="#在-linux-上管理加密密鑰的最佳體驗" aria-label="Permalink to “在 Linux 上管理加密密鑰的最佳體驗”">​</a></h1><p>存儲 SSH 的加密秘鑰和記住密碼一直是一個讓人頭疼的問題。但是不幸的是，在當前這個充滿了惡意黑客和攻擊的世界中，基本的安全預防是必不可少的。對於許多普通用户來説，大多數人只能是記住密碼，也可能尋找到一個好程序去存儲密碼，正如我們提醒這些用户不要在每個網站採用相同的密碼。但是對於在各個 IT 領域的人們，我們需要將這個事情提高一個層面。我們需要使用像 SSH 密鑰這樣的加密秘鑰，而不只是密碼。</p><p>設想一個場景：我有一個運行在雲上的服務器，用作我的主 git 庫。我有很多台工作電腦，所有這些電腦都需要登錄到這個中央服務器去做 push 與 pull 操作。這裏我設置 git 使用 SSH。當 git 使用 SSH 時，git 實際上是以 SSH 的方式登錄到服務器，就好像你通過 SSH 命令打開一個服務器的命令列一樣。為了把這些配置好，我在我的 .ssh 目錄下創建一個配置文件，其中包含一個有服務器名字、主機名、登錄用户、密鑰文件路徑等信息的主機項。之後我可以通過輸入如下命令來測試這個配置是否正確。</p><pre><code>ssh gitserver
</code></pre><p>很快我就可以訪問到服務器的 bash shell。現在我可以配置 git 使用相同配置項以及存儲的密鑰來登錄服務器。這很簡單，只是有一個問題：對於每一個我要用它登錄服務器的電腦，我都需要有一個密鑰文件，那意味着需要密鑰文件會放在很多地方。我會在當前這台電腦上存儲這些密鑰文件，我的其他電腦也都需要存儲這些。就像那些有特別多的密碼的用户一樣，我們這些 IT 人員也被這些特別多的密鑰文件淹沒。怎麼辦呢？</p><h3 id="清理" tabindex="-1">清理 <a class="header-anchor" href="#清理" aria-label="Permalink to “清理”">​</a></h3><p>在我們開始幫助你管理密鑰之前，你需要有一些密鑰應該怎麼使用的基礎知識，以及明白我們下面的提問的意義所在。同時，有個前提，也是最重要的，你應該知道你的公鑰和私鑰該放在哪裏。然後假設你應該知道：</p><ol><li>公鑰和私鑰之間的差異；</li><li>為什麼你不可以從公鑰生成私鑰，但是反之則可以？</li><li><code>authorized_keys</code> 文件的目的以及裏面包含什麼內容；</li><li>如何使用私鑰去登錄一個你的對應公鑰存儲在其上的 <code>authorized_keys</code> 文件中的服務器。</li></ol><p><img src="http://www.linux.com/images/stories/41373/key-management-diagram.png" alt=""></p><p>這裏有一個例子。當你在亞馬遜的網絡服務上創建一個雲服務器，你必須提供一個用於連接你的服務器的 SSH 密鑰。每個密鑰都有一個公開的部分（公鑰）和私密的部分（私鑰）。你要想讓你的服務器安全，乍看之下你可能應該將你的私鑰放到服務器上，同時你自己帶着公鑰。畢竟，你不想你的服務器被公開訪問，對嗎？但是實際上的做法正好是相反的。</p><p>你應該把自己的公鑰放到 AWS 服務器，同時你持有用於登錄服務器的私鑰。你需要保護好私鑰，並讓它處於你的控制之中，而不是放在一些遠程服務器上，正如上圖中所示。</p><p>原因如下：如果公鑰被其他人知道了，它們不能用於登錄服務器，因為他們沒有私鑰。進一步説，如果有人成功攻入你的服務器，他們所能找到的只是公鑰，他們不可以從公鑰生成私鑰。同時，如果你在其他的服務器上使用了相同的公鑰，他們不可以使用它去登錄別的電腦。</p><p>這就是為什麼你要把你自己的公鑰放到你的服務器上以便通過 SSH 登錄這些服務器。你持有這些私鑰，不要讓這些私鑰脱離你的控制。</p><p>但是還有一點麻煩。試想一下我 git 服務器的例子。我需要做一些抉擇。有時我登錄架設在別的地方的開發服務器，而在開發服務器上，我需要連接我的 git 服務器。如何使我的開發服務器連接 git 服務器？顯然是通過使用私鑰，但這樣就會有問題。在該場景中，需要我把私鑰放置到一個架設在別的地方的服務器上，這相當危險。</p><p>一個進一步的場景：如果我要使用一個密鑰去登錄許多的服務器，怎麼辦？如果一個入侵者得到這個私鑰，這個人就能用這個私鑰得到整個服務器網絡的權限，這可能帶來一些嚴重的破壞，這非常糟糕。</p><p>同時，這也帶來了另外一個問題，我真的應該在這些其他服務器上使用相同的密鑰嗎？因為我剛才描述的，那會非常危險的。</p><p>最後，這聽起來有些混亂，但是確實有一些簡單的解決方案。讓我們有條理地組織一下。</p><p>（注意，除了登錄服務器，還有很多地方需要私鑰密鑰，但是我提出的這個場景可以向你展示當你使用密鑰時你所面對的問題。）</p><h3 id="常規口令" tabindex="-1">常規口令 <a class="header-anchor" href="#常規口令" aria-label="Permalink to “常規口令”">​</a></h3><p>當你創建你的密鑰時，你可以選擇是否包含一個密鑰使用時的口令。有了這個口令，私鑰文件本身就會被口令所加密。例如，如果你有一個公鑰存儲在服務器上，同時你使用私鑰去登錄服務器的時候，你會被提示輸入該口令。沒有口令，這個密鑰是無法使用的。或者你也可以配置你的密鑰不需要口令，然後只需要密鑰文件就可以登錄服務器了。</p><p>一般來説，不使用口令對於用户來説是更方便的，但是在很多情況下我強烈建議使用口令，原因是，如果私鑰文件被偷了，偷密鑰的人仍然不可以使用它，除非他或者她可以找到口令。在理論上，這個將節省你很多時間，因為你可以在攻擊者發現口令之前，從服務器上刪除公鑰文件，從而保護你的系統。當然還有一些使用口令的其它原因，但是在很多場合這個原因對我來説更有價值。（舉一個例子，我的 Android 平板上有 VNC 軟件。平板上有我的密鑰。如果我的平板被偷了之後，我會馬上從服務器上刪除公鑰，使得它的私鑰沒有作用，無論有沒有口令。）但是在一些情況下我不使用口令，是因為我正在登錄的服務器上沒有什麼有價值的數據，這取決於情境。</p><h3 id="服務器基礎設施" tabindex="-1">服務器基礎設施 <a class="header-anchor" href="#服務器基礎設施" aria-label="Permalink to “服務器基礎設施”">​</a></h3><p>你如何設計自己服務器的基礎設施將會影響到你如何管理你的密鑰。例如，如果你有很多用户登錄，你將需要決定每個用户是否需要一個單獨的密鑰。（一般來説，應該如此；你不會想在用户之間共享私鑰。那樣當一個用户離開組織或者失去信任時，你可以刪除那個用户的公鑰，而不需要必須給其他人生成新的密鑰。相似地，通過共享密鑰，他們能以其他人的身份登錄，這就更糟糕了。）但是另外一個問題是你如何配置你的服務器。舉例來説，你是否使用像 Puppet 這樣工具配置大量的服務器？你是否基於你自己的鏡像創建大量的服務器？當你複製你的服務器，是否每一個的密鑰都一樣？不同的雲服務器軟件允許你配置如何選擇；你可以讓這些服務器使用相同的密鑰，也可以給每一個服務器生成一個新的密鑰。</p><p>如果你在操作這些複製的服務器，如果用户需要使用不同的密鑰登錄兩個不同但是大部分都一樣的系統，它可能導致混淆。但是另一方面，服務器共享相同的密鑰會有安全風險。或者，第三，如果你的密鑰有除了登錄之外的需要（比如掛載加密的驅動），那麼你會在很多地方需要相同的密鑰。正如你所看到的，你是否需要在不同的服務器上使用相同的密鑰不是我能為你做的決定；這其中有權衡，你需要自己去決定什麼是最好的。</p><p>最終，你可能會有：</p><ul><li>需要登錄的多個服務器</li><li>多個用户登錄到不同的服務器，每個都有自己的密鑰</li><li>每個用户使用多個密鑰登錄到不同的服務器</li></ul><p>（如果你正在別的情況下使用密鑰，這個同樣的普適理論也能應用於如何使用密鑰，需要多少密鑰，它們是否共享，你如何處理公私鑰等方面。）</p><h3 id="安全方法" tabindex="-1">安全方法 <a class="header-anchor" href="#安全方法" aria-label="Permalink to “安全方法”">​</a></h3><p>瞭解你的基礎設施和特有的情況，你需要組合一個密鑰管理方案，它會指導你如何去分發和存儲你的密鑰。比如，正如我之前提到的，如果我的平板被偷了，我會從我服務器上刪除公鑰，我希望這在平板在用於訪問服務器之前完成。同樣的，我會在我的整體計劃中考慮以下內容：</p><ol><li>私鑰可以放在移動設備上，但是必須包含口令；</li><li>必須有一個可以快速地從服務器上刪除公鑰的方法。</li></ol><p>在你的情況中，你可能決定你不想在自己經常登錄的系統上使用口令；比如，這個系統可能是一個開發者一天登錄多次的測試機器。這沒有問題，但是你需要調整一點你的規則。你可以添加一條規則：不可以通過移動設備登錄該機器。換句話説，你需要根據自己的狀況構建你的準則，不要假設某個方案放之四海而皆準。</p><h3 id="軟件" tabindex="-1">軟件 <a class="header-anchor" href="#軟件" aria-label="Permalink to “軟件”">​</a></h3><p>至於軟件，令人吃驚的是，現實世界中並沒有很多好的、可靠的存儲和管理私鑰的軟件解決方案。但是應該有嗎？考慮下這個，如果你有一個程序存儲你所有服務器的全部密鑰，並且這個程序被一個快捷的密鑰鎖住，那麼你的密鑰就真的安全了嗎？或者類似的，如果你的密鑰被放置在你的硬盤上，用於 SSH 程序快速訪問，密鑰管理軟件是否真正提供了任何保護嗎？</p>`,33)),l("p",null,[t[1]||(t[1]=n("但是對於整體基礎設施和創建/管理公鑰來説，有許多的解決方案。我已經提到了 Puppet，在 Puppet 的世界中，你可以創建模組以不同的方式管理你的服務器。這個想法是服務器是動態的，而且不需要精確地複製彼此。",-1)),i(e,{href:"http://manuel.kiessling.net/2014/03/26/building-manageable-server-infrastructures-with-puppet-part-4/"},{default:o(()=>[...t[0]||(t[0]=[n("這裏有一個聰明的方法",-1)])]),_:1}),t[2]||(t[2]=n("，在不同的服務器上使用相同的密鑰，但是對於每一個用户使用不同的 Puppet 模組。這個方案可能適合你，也可能不適合你。",-1))]),l("p",null,[t[4]||(t[4]=n("或者，另一個選擇就是完全換個不同的檔位。在 Docker 的世界中，你可以採取一個不同的方式，正如",-1)),i(e,{href:"http://blog.docker.com/2014/06/why-you-dont-need-to-run-sshd-in-docker/"},{default:o(()=>[...t[3]||(t[3]=[n("關於 SSH 和 Docker Blog",-1)])]),_:1}),t[5]||(t[5]=n("所描述的那樣。",-1))]),t[23]||(t[23]=l("p",null,"但是怎麼樣管理私鑰？如果你搜索過的話，你無法找到很多可以選擇的軟件，原因我之前提到過；私鑰存放在你的硬盤上，一個管理軟件可能無法提到更多額外的安全。但是我使用這種方法來管理我的密鑰：",-1)),t[24]||(t[24]=l("p",null,[n("首先，我的 "),l("code",null,".ssh/config"),n(" 文件中有很多的主機項。我要登錄的都有一個主機項，但是有時我對於一個單獨的主機有不止一項。如果我有很多登錄方式，就會出現這種情況。對於放置我的 git 庫的服務器來説，我有兩個不同的登錄項；一個限制於 git，另一個用於一般用途的 bash 訪問。這個為 git 設置的登錄選項在機器上有極大的限制。還記得我之前説的我存儲在遠程開發機器上的 git 密鑰嗎？好了。雖然這些密鑰可以登錄到我其中一個服務器，但是使用的賬號是被嚴格限制的。")],-1)),l("p",null,[t[7]||(t[7]=n("其次，大部分的私鑰都包含口令。（對於需要多次輸入口令的情況，考慮使用 ",-1)),i(e,{href:"http://blog.docker.com/2014/06/why-you-dont-need-to-run-sshd-in-docker/"},{default:o(()=>[...t[6]||(t[6]=[n("ssh-agent",-1)])]),_:1}),t[8]||(t[8]=n("。）",-1))]),t[25]||(t[25]=l("p",null,"再次，我有一些我想要更加小心地保護的服務器，我不會把這些主機項放在我的 host 文件中。這更加接近於社會工程方面，密鑰文件還在，但是可能需要攻擊者花費更長的時間去找到這個密鑰文件，分析出來它們對應的機器。在這種情況下，我就需要手動打出來一條長長的 SSH 命令。（沒那麼可怕。）",-1)),t[26]||(t[26]=l("p",null,"同時你可以看出來我沒有使用任何特別的軟件去管理這些私鑰。",-1)),t[27]||(t[27]=l("h2",{id:"無放之四海而皆準的方案",tabindex:"-1"},[n("無放之四海而皆準的方案 "),l("a",{class:"header-anchor",href:"#無放之四海而皆準的方案","aria-label":"Permalink to “無放之四海而皆準的方案”"},"​")],-1)),t[28]||(t[28]=l("p",null,[n("我們偶爾會在 linux.com 收到一些問題，詢問管理密鑰的好軟件的建議。但是退一步看，這個問題事實上需要重新思考，因為沒有一個普適的解決方案。你問的問題應該基於你自己的狀況。你是否簡單地嘗試找到一個位置去存儲你的密鑰文件？你是否尋找一個方法去管理多用户問題，其中每個人都需要將他們自己的公鑰插入到 "),l("code",null,"authorized_keys"),n(" 文件中？")],-1)),t[29]||(t[29]=l("p",null,"通過這篇文章，我已經囊括了這方面的基礎知識，希望到此你明白如何管理你的密鑰，並且，只有當你問出了正確的問題，無論你尋找任何軟件（甚至你需要另外的軟件），它都會出現。",-1)),t[30]||(t[30]=l("hr",null,null,-1)),l("p",null,[t[10]||(t[10]=n("via: ",-1)),i(e,{href:"http://www.linux.com/learn/tutorials/838235-how-to-best-manage-encryption-keys-on-linux"},{default:o(()=>[...t[9]||(t[9]=[n("http://www.linux.com/learn/tutorials/838235-how-to-best-manage-encryption-keys-on-linux",-1)])]),_:1})]),l("p",null,[t[14]||(t[14]=n("作者：",-1)),i(e,{href:"http://www.linux.com/community/forums/person/62256"},{default:o(()=>[...t[11]||(t[11]=[n("Jeff Cogswell",-1)])]),_:1}),t[15]||(t[15]=n(" 譯者：",-1)),i(e,{href:"https://github.com/mudongliang"},{default:o(()=>[...t[12]||(t[12]=[n("mudongliang",-1)])]),_:1}),t[16]||(t[16]=n(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[13]||(t[13]=[n("wxy",-1)])]),_:1})]),l("p",null,[t[19]||(t[19]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[17]||(t[17]=[n("LCTT",-1)])]),_:1}),t[20]||(t[20]=n(" 原創翻譯，",-1)),i(e,{href:"https://linux.cn/"},{default:o(()=>[...t[18]||(t[18]=[n("Linux中國",-1)])]),_:1}),t[21]||(t[21]=n(" 榮譽推出",-1))])])}const y=p(d,[["render",m]]);export{k as __pageData,y as default};
